package scheduledtask

import "time"

// Execution history projection limit (contract §4.4: the API shows the most
// recent 50 records).
const (
	DefaultExecutionLimit = 50
	MaxExecutionLimit     = 50
)

// Repository is the scheduled-task persistence contract. The file-backed
// implementation lives in file_repository.go; the scheduler slice depends
// only on this interface.
type Repository interface {
	// Create persists a new task. TaskID, Version, ThreadID, CreatedAt and
	// UpdatedAt from the input are discarded and regenerated by Core.
	Create(task Task) (Task, error)

	// Get returns one task. Tombstoned and unknown IDs return
	// ErrTaskNotFound.
	Get(taskID string) (Task, error)

	// List returns all non-tombstoned tasks ordered by CreatedAt then TaskID.
	List() ([]Task, error)

	// Update applies mutate under a version compare-and-swap: a stale
	// expectedVersion returns ErrVersionConflict. The repository forces
	// TaskID/CreatedAt continuity, increments Version and stamps UpdatedAt.
	Update(taskID string, expectedVersion int64, mutate func(Task) (Task, error)) (Task, error)

	// Delete writes a tombstone under a version compare-and-swap. The task
	// disappears from Get/List immediately; the tombstone record stays in the
	// journal for replay and future FileStore generation compaction. A
	// non-empty idempotencyKey records the outcome so a retry after a lost
	// 204 can replay the success instead of returning ErrTaskNotFound.
	Delete(taskID string, expectedVersion int64, idempotencyKey string) error

	// SetPaused / SetResumed flip Enabled through the same CAS path.
	SetPaused(taskID string, expectedVersion int64) (Task, error)
	SetResumed(taskID string, expectedVersion int64) (Task, error)

	// BindThread records the task's stable dedicated thread (created by Core
	// at first execution).
	BindThread(taskID string, expectedVersion int64, threadID string) (Task, error)

	// ConsumeOccurrence records that a due occurrence was processed
	// (scheduled or misfire trigger, success, failure or skip). It
	// increments ConsumedOccurrences and advances LastProcessedOccurrence.
	ConsumeOccurrence(taskID string, occurrence time.Time) (Task, error)

	// MarkCompleted transitions a schedule-exhausted task to completed.
	MarkCompleted(taskID string) (Task, error)

	// AppendExecution appends an execution-history record.
	//
	// Empty ExecutionID creates a new execution: the repository generates
	// the exec_ ID and deduplicates on the idempotency key — for
	// scheduled/misfire triggers (task_id, scheduled_for), for
	// manual triggers the caller-supplied IdempotencyKey. A duplicate
	// returns the already-persisted execution with created=false instead of
	// creating a second one (restart / transport-retry dedup).
	//
	// A non-empty ExecutionID appends a status transition for that existing
	// execution; readers fold to the newest record per ExecutionID.
	// Transitions out of a terminal status return ErrInvalidTransition.
	// Transitions also report created=false.
	AppendExecution(taskID string, exec Execution) (Execution, bool, error)

	// ListExecutions folds each ExecutionID to its newest record and returns
	// them newest-first by scheduled_for/started_at. limit <= 0 defaults to
	// 50 and any limit is capped at 50.
	ListExecutions(taskID string, limit int) ([]Execution, error)

	// SealInterrupted appends status=interrupted for every queued/running
	// execution of the task (Core restart recovery, contract §8.1). It
	// returns the sealed records; already-terminal executions are untouched.
	SealInterrupted(taskID string, clock Clock) ([]Execution, error)

	// Close releases journals and other resources.
	Close() error
}
